"use strict";
// A playlist that hands out iterators over its tracks and remembers the
// last one it made or was handed. Its loader picks its part with a computed
// require() specifier, which scriptc does not compile natively, so the
// package runs in a Node island.
const { createRequire } = require("node:module");
const load = createRequire(__filename);
const [deck] = ["./lib/deck"].map((p) => load(p));

exports.queue = deck.queue;
exports.sides = deck.sides;
exports.endless = deck.endless;
exports.current = deck.current;
exports.currentSides = deck.current;
exports.currentStepper = deck.current;
exports.currentLoose = deck.current;
exports.hold = deck.hold;
exports.isCurrent = deck.isCurrent;
exports.isCurrentSides = deck.isCurrent;
exports.isCurrentStepper = deck.isCurrent;
exports.isCurrentLoose = deck.isCurrent;
exports.upcoming = deck.upcoming;
exports.withCurrent = deck.withCurrent;
